publication({ id: "herrmann2008-antisocial-punishment", title: "Antisocial Punishment Across Societies", authors: ["Benedikt Herrmann", "Christian Thöni", "Simon Gächter"], year: 2008,
  doi: "10.1126/science.1153808", url: "https://alexandria.unisg.ch/entities/publication/20101def-497f-445e-a940-5e03f7844524", journal: "Science", volume: "319", issue: "5868", pages: "1362-1367",
  extent: "selected-published-main-experiments-results-and-country-associations", locators: ["Main pp. 1362-1363: Experiments, fixed groups, contribution and deduction-point rules", "Main pp. 1363-1365: punishment categories, contribution results, Figures 1-3 and Table 1", "Main pp. 1365-1366: country indicators, Table 2 associations and alternative motives"],
  limit: "The author-institution metadata and selected published main text were read from the six-page PDF publicly linked by author Christian Thöni at https://people.unil.ch/christianthoeni/list-of-publications/ (Google Drive file 1mxpaP4N3VQe5QBQvD_17MTKADFaBxunG), with local OCR assistance. Supporting Methods/tables, treatment order/counterbalancing, raw data and regression calculations were not independently checked. The 1120 university undergraduates in sixteen participant pools are not national representative samples. Antisocial means punishing someone contributing at least as much as the punisher; behavior does not uniquely identify revenge, dominance or other motives." });
study({ id: "herrmann2008-fixed-group-games", sourceId: "herrmann2008-antisocial-punishment", system: "1120 university undergraduates across sixteen participant pools; anonymous computer-mediated groups of four",
  locators: ["Main pp. 1362-1363: Experiments, fixed groups, contribution and deduction-point rules", "Main pp. 1363-1365: punishment categories, contribution results, Figures 1-3 and Table 1"],
  preparation: "Use the same monetary public-goods rules across pools: twenty-token individual endowment and return of 0.4 tokens to each member per contributed token. Compare ten fixed-group rounds without punishment with ten rounds permitting simultaneous peer deduction points after contribution feedback; each point costs the punisher one token and reduces its target's earnings by three.",
  observable: "Contributions, punishment expenditures relative to punisher/target contributions and subsequent contribution changes", finding: "Antisocial punishment varies across pools. The main text reports at least weakly significant punishment-associated contribution gains in eleven pools and no significant gain in five; more antisocial punishment is associated with weaker contribution gains, not a universal zero effect.",
  limitations: ["The five nonsignificant contrasts are not equivalence tests or proof of exactly no benefit. Pool variation and punishment-behavior regressions are not randomized cultural mechanisms.", "Fixed-group dependence, paired condition histories and unread treatment order prevent treating every round or condition as an independent experiment. Punishment motives are proposed explanations, not experimentally isolated mediators."] });
observation({ id: "antisocial-punishment-boundary", name: "Punishment benefit varies across sampled groups", studyId: "herrmann2008-fixed-group-games", statement: "The main article reports variable antisocial punishment, defined relative to the punisher's contribution, and variable contribution gains when punishment is available: eleven pools have at least weakly significant gains and five lack significant gains. Antisocial punishment is associated with weaker gains; nonsignificance does not establish a zero effect or a uniquely proven motive." });
study({ id: "herrmann2008-country-associations", sourceId: "herrmann2008-antisocial-punishment", studyType: "primary-observation", system: "Country indicators linked to the same sixteen undergraduate participant pools, not new randomized cohorts",
  locators: ["Main pp. 1365-1366: country indicators, Table 2 associations and alternative motives"],
  preparation: "Relate laboratory punishment expenditures to externally compiled World Values Survey civic-cooperation measures and a rule-of-law indicator, adjusting for stated contributions, period and participant characteristics in source-reported regressions.",
  observable: "Associations of antisocial punishment with country-level civic-norm and rule-of-law indicators", finding: "The source reports negative associations between antisocial punishment and both country indicators; these are comparisons of measured background conditions, not interventions on a society's law or culture.",
  limitations: ["Ecological linkage of national indicators to selected student behavior does not identify individual exposure, cultural transmission or representative national punishment rates.", "Country indicators, participant-pool selection and potential shared causes were not independently manipulated; Table 2 and supplemental robustness results were not recomputed."] });
observation({ id: "punishment-country-association", name: "Country background is an observational correlate", studyId: "herrmann2008-country-associations", statement: "The source reports lower antisocial punishment in participant pools from countries with stronger measured civic-cooperation norms and rule of law. These contextual associations do not establish a randomized cultural cause or representative societal behavior." });

